import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireForms Release Notes — 2021","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireForms/aireforms-2021.md","filePath":"aireblock-releases/AireForms/aireforms-2021.md","lastUpdated":1786967125000}`),a={name:`aireblock-releases/AireForms/aireforms-2021.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireforms-release-notes-—-2021" tabindex="-1"><span class="fsc-product"><img src="/aireforms-icon.png"> AireForms Release Notes — 2021</span> <a class="header-anchor" href="#aireforms-release-notes-—-2021" aria-label="Permalink to “AireForms Release Notes — 2021”">​</a></h1><p>This page contains the AireForms releases published during 2021.</p><h2 id="version-5-8-1-—-pdf-api" tabindex="-1">Version 5.8.1 — PDF API <a class="header-anchor" href="#version-5-8-1-—-pdf-api" aria-label="Permalink to “Version 5.8.1 — PDF API”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 6, 2021</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added the ability to return a PDF as a Base64 JSON object via API</li></ul><h2 id="version-5-8-0-—-correlation-ids-logos-aireflow" tabindex="-1">Version 5.8.0 — Correlation IDs, Logos &amp; AireFlow <a class="header-anchor" href="#version-5-8-0-—-correlation-ids-logos-aireflow" aria-label="Permalink to “Version 5.8.0 — Correlation IDs, Logos &amp; AireFlow”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 8, 2021</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for multiple form definition directories</li><li>Added support for correlation IDs on Wizard forms</li><li>Added support for correlation IDs on Business (clinician) forms</li><li>Added form-level logo overrides rather than relying only on the organisation logo</li><li>Added support for SVG logos</li><li>Added an AireFlow delivery channel for Wizard forms</li></ul><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved logging for the AireGlu delivery channel</li><li>Passed organisational context to APIs for form and building block definitions</li><li>Improved operational logging and alerting</li><li>Improved validation for the form builder</li><li>Improved accessibility of the Rich Text Accordion control</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue with the Date Time control in read view when using a date-time offset</li><li>Hid the pre-population rule on building blocks when a form is configured as Single Pass</li></ul><h2 id="version-5-7-6-—-date-time-read-view-fix" tabindex="-1">Version 5.7.6 — Date Time Read View Fix <a class="header-anchor" href="#version-5-7-6-—-date-time-read-view-fix" aria-label="Permalink to “Version 5.7.6 — Date Time Read View Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 18, 2021</p></blockquote><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue where the Date Time control rendered incorrectly in read view</li></ul><h2 id="version-5-7-4-—-image-fidelity-fix" tabindex="-1">Version 5.7.4 — Image Fidelity Fix <a class="header-anchor" href="#version-5-7-4-—-image-fidelity-fix" aria-label="Permalink to “Version 5.7.4 — Image Fidelity Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 1, 2021</p></blockquote><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue with the picture/upload control when image fidelity was not set</li></ul><h2 id="version-5-7-2-—-reference-data-management-fixes" tabindex="-1">Version 5.7.2 — Reference Data Management Fixes <a class="header-anchor" href="#version-5-7-2-—-reference-data-management-fixes" aria-label="Permalink to “Version 5.7.2 — Reference Data Management Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 22, 2021</p></blockquote><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue in the new management UI when creating a new reference data class</li><li>Removed UI buttons that allowed users to up-version forms that were not the latest version</li></ul><h2 id="version-5-7-1-—-custom-rule-validation" tabindex="-1">Version 5.7.1 — Custom Rule Validation <a class="header-anchor" href="#version-5-7-1-—-custom-rule-validation" aria-label="Permalink to “Version 5.7.1 — Custom Rule Validation”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 14, 2021</p></blockquote><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Removed custom rule validation that was blocking valid forms from being saved</li></ul><h2 id="version-5-7-0-—-multi-tenancy-form-builder-ux" tabindex="-1">Version 5.7.0 — Multi-Tenancy &amp; Form Builder UX <a class="header-anchor" href="#version-5-7-0-—-multi-tenancy-form-builder-ux" aria-label="Permalink to “Version 5.7.0 — Multi-Tenancy &amp; Form Builder UX”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 9, 2021</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added multi-tenancy support for lazy serving of reference data</li><li>Added support for serving static files such as logos in a multi-tenant context</li><li>Added support for AireGlu tenant affinity</li><li>Added discard warnings when navigating away from edit screens for reference data and forms</li></ul><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved form builder UX to make Save and Exit clearer and highlight unsaved changes</li><li>Added tolerance for whitespace in reference data item validation</li><li>Improved display of long custom relevance rules (XPath) using a textarea</li><li>Updated definition provider interfaces to support multi-tenancy</li><li>Improved performance by loading reference data asynchronously</li><li>Removed old management screens</li><li>Improved the UI where more than three actions exist on a building block</li><li>Changed form definition load/save actions to asynchronous operations for improved performance</li></ul><h2 id="version-5-6-6-—-pdf-rich-text-fix" tabindex="-1">Version 5.6.6 — PDF Rich Text Fix <a class="header-anchor" href="#version-5-6-6-—-pdf-rich-text-fix" aria-label="Permalink to “Version 5.6.6 — PDF Rich Text Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 3, 2021</p></blockquote><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved a PDF generation issue where explanatory text or calculated values referenced a Rich Text control containing unclosed <code>br</code> tags</li></ul><h2 id="version-5-6-5-—-pdf-angle-bracket-fix" tabindex="-1">Version 5.6.5 — PDF Angle Bracket Fix <a class="header-anchor" href="#version-5-6-5-—-pdf-angle-bracket-fix" aria-label="Permalink to “Version 5.6.5 — PDF Angle Bracket Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 1, 2021</p></blockquote><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue where PDF generation stripped data enclosed in angle brackets</li></ul><h2 id="version-5-6-4-—-multi-tenant-instance-creation" tabindex="-1">Version 5.6.4 — Multi-Tenant Instance Creation <a class="header-anchor" href="#version-5-6-4-—-multi-tenant-instance-creation" aria-label="Permalink to “Version 5.6.4 — Multi-Tenant Instance Creation”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 19, 2021</p></blockquote><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue with instance creation for a patient in a multi-tenanted environment</li></ul><h2 id="version-5-6-3-—-extract-api-fix" tabindex="-1">Version 5.6.3 — Extract API Fix <a class="header-anchor" href="#version-5-6-3-—-extract-api-fix" aria-label="Permalink to “Version 5.6.3 — Extract API Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 17, 2021</p></blockquote><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an Extract API issue affecting multiple building blocks</li></ul><h2 id="version-5-6-2-—-extract-api-git-conflict-handling" tabindex="-1">Version 5.6.2 — Extract API &amp; Git Conflict Handling <a class="header-anchor" href="#version-5-6-2-—-extract-api-git-conflict-handling" aria-label="Permalink to “Version 5.6.2 — Extract API &amp; Git Conflict Handling”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 2, 2021</p></blockquote><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved file conflict handling for the gitcron container when running in read-only mode</li></ul><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an Extract API defect involving null values</li></ul><h2 id="version-5-6-1-—-demo-user-fix" tabindex="-1">Version 5.6.1 — Demo User Fix <a class="header-anchor" href="#version-5-6-1-—-demo-user-fix" aria-label="Permalink to “Version 5.6.1 — Demo User Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 30, 2021</p></blockquote><h3 id="🐞-bug-fixes-10" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-10" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue where the demo user could not access the list of available forms</li></ul><h2 id="version-5-6-0-—-new-management-screens-api-improvements" tabindex="-1">Version 5.6.0 — New Management Screens &amp; API Improvements <a class="header-anchor" href="#version-5-6-0-—-new-management-screens-api-improvements" aria-label="Permalink to “Version 5.6.0 — New Management Screens &amp; API Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 30, 2021</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Enabled the new management screens</li><li>Added a new form definition API to support testing and other use cases</li><li>Added timezone localisation support for PDF generation time</li></ul><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved the Extract API to return every data item in a building block or form</li><li>Improved the form definition API, including information to identify controls storing Base64 strings such as images</li><li>Improved the create method API to make it idempotent when called multiple times with the same identifier by an external system</li></ul><h3 id="🐞-bug-fixes-11" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-11" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved numeric validation on Safari where a numeric field could be stripped from the data while still passing validation</li><li>Fixed instance creation without a form version when the latest version was withdrawn</li><li>Resolved an IE11 issue where integer fields could be submitted with a trailing decimal point</li></ul><h2 id="version-5-5-0-—-aireglu-health-checks" tabindex="-1">Version 5.5.0 — AireGlu &amp; Health Checks <a class="header-anchor" href="#version-5-5-0-—-aireglu-health-checks" aria-label="Permalink to “Version 5.5.0 — AireGlu &amp; Health Checks”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 14, 2021</p></blockquote><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved AireGlu integration to allow staging endpoints to be called</li><li>Improved the health check endpoint to support deep checks such as database and filesystem checks</li></ul><h2 id="version-5-4-0-—-pod-launcher-runtime-security" tabindex="-1">Version 5.4.0 — POD Launcher &amp; Runtime Security <a class="header-anchor" href="#version-5-4-0-—-pod-launcher-runtime-security" aria-label="Permalink to “Version 5.4.0 — POD Launcher &amp; Runtime Security”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 7, 2021</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a new POD form launcher and configuration</li><li>Added POD launcher redirect after form submission</li><li>Added POD form inactivity timeout and redirect</li><li>Added the ability to pass Base64-encoded form context to Single Pass forms</li><li>Added configurable frame ancestors policy per deployment</li><li>Added a hook to display a submission error when reCAPTCHA fails</li><li>Added missing XPath axis support</li></ul><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Replaced Draft.js with React Quill for Rich Text fields to support digital dictation from iOS devices</li><li>Updated the form-to-XSD generator to support controls that store XML data</li><li>Removed <code>unsafe-eval</code> from the Forms runtime Content Security Policy</li><li>Replaced use of the raw XPath parser with <code>parsescript</code> from FontoXPath</li></ul><h3 id="🐞-bug-fixes-12" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-12" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved confusing chevron usage in Master Child repeats</li><li>Resolved Rich Text rendering in Master Child headers</li><li>Prevented the browser Back action from unexpectedly navigating users away from a form</li></ul><h2 id="version-5-3-0-—-security-performance-aireflow-integration" tabindex="-1">Version 5.3.0 — Security, Performance &amp; AireFlow Integration <a class="header-anchor" href="#version-5-3-0-—-security-performance-aireflow-integration" aria-label="Permalink to “Version 5.3.0 — Security, Performance &amp; AireFlow Integration”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 11, 2021</p></blockquote><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved submitted data sanitisation</li><li>Extended cache-control headers to all resources</li><li>Extended AireFlow integration to share information from submitted Wizard forms</li><li>Improved plugin resolver logging</li><li>Improved performance of Patient Forms APIs</li><li>Migrated logging configuration to the appsettings provider</li><li>Excluded withdrawn form data from rule-based building block pre-population</li></ul><h3 id="♿-accessibility" tabindex="-1">♿ Accessibility <a class="header-anchor" href="#♿-accessibility" aria-label="Permalink to “♿ Accessibility”">​</a></h3><ul><li>Resolved an AA compliance issue with subtext on the validation popup</li></ul><h3 id="🐞-bug-fixes-13" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-13" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved inconsistent font size in PDF footers</li><li>Resolved an IE11 issue with Fonto XML</li><li>Correctly escaped the <code>languageCode</code> parameter sent to <code>ResourceInstance</code></li><li>Fixed logo positioning and headers for GDS-themed forms</li><li>Fixed schema API ordering for multi-line repeat elements</li><li>Fixed collapsing and expanding repeat iterations with summary controls</li><li>Fixed PDF rendering for partially completed ordered and unordered lists</li></ul><h2 id="version-5-2-1-—-recaptcha-fix" tabindex="-1">Version 5.2.1 — reCAPTCHA Fix <a class="header-anchor" href="#version-5-2-1-—-recaptcha-fix" aria-label="Permalink to “Version 5.2.1 — reCAPTCHA Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 23, 2021</p></blockquote><h3 id="🐞-bug-fixes-14" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-14" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved a reCAPTCHA issue caused by a Google domain change and the AireForms Content Security Policy</li></ul><h2 id="version-5-2-0-—-pdf-improvements" tabindex="-1">Version 5.2.0 — PDF Improvements <a class="header-anchor" href="#version-5-2-0-—-pdf-improvements" aria-label="Permalink to “Version 5.2.0 — PDF Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 14, 2021</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for PDF subheadings, such as organisation address details</li><li>Added support for a logo in the PDF footer</li></ul><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved PDF styling including font sizes and colours</li><li>Improved support for building block read mode</li><li>Improved error handling for discard actions</li></ul><h3 id="🐞-bug-fixes-15" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-15" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved ordered lists rendering as unordered lists in PDFs</li><li>Resolved an autofill issue in the building block designer</li></ul><h2 id="version-5-1-1-—-wizard-data-rehydration" tabindex="-1">Version 5.1.1 — Wizard Data Rehydration <a class="header-anchor" href="#version-5-1-1-—-wizard-data-rehydration" aria-label="Permalink to “Version 5.1.1 — Wizard Data Rehydration”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 7, 2021</p></blockquote><h3 id="🐞-bug-fixes-16" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-16" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue with Wizard form data rehydration when no prior data exists</li></ul><h2 id="version-5-1-0-—-delivery-channel-response-messages" tabindex="-1">Version 5.1.0 — Delivery Channel Response Messages <a class="header-anchor" href="#version-5-1-0-—-delivery-channel-response-messages" aria-label="Permalink to “Version 5.1.0 — Delivery Channel Response Messages”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 30, 2021</p></blockquote><h3 id="✨-new-features-6" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-6" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for displaying a delivery channel response message without providing a redirect URL</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Refined the form definition cloner</li><li>Improved cross-building-block XPath unit test coverage</li></ul><h3 id="🐞-bug-fixes-17" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-17" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an IE11 bug in the Annotated Image Upload control</li><li>Fixed error logging for unauthenticated users on management screens</li><li>Resolved a sticky footer issue on some screen resolutions in Wizard layout</li></ul><h2 id="version-5-0-4-—-ie11-instance-function-fix" tabindex="-1">Version 5.0.4 — IE11 Instance Function Fix <a class="header-anchor" href="#version-5-0-4-—-ie11-instance-function-fix" aria-label="Permalink to “Version 5.0.4 — IE11 Instance Function Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 23, 2021</p></blockquote><h3 id="🐞-bug-fixes-18" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-18" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue viewing forms in IE11 when using the <code>instance</code> function</li></ul><h2 id="version-5-0-3-—-nhs-mail-fix" tabindex="-1">Version 5.0.3 — NHS Mail Fix <a class="header-anchor" href="#version-5-0-3-—-nhs-mail-fix" aria-label="Permalink to “Version 5.0.3 — NHS Mail Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 22, 2021</p></blockquote><h3 id="🐞-bug-fixes-19" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-19" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue connecting to the old NHS Mail Exchange service</li></ul><h2 id="version-5-0-2-—-demo-pdf-fixes" tabindex="-1">Version 5.0.2 — Demo &amp; PDF Fixes <a class="header-anchor" href="#version-5-0-2-—-demo-pdf-fixes" aria-label="Permalink to “Version 5.0.2 — Demo &amp; PDF Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 19, 2021</p></blockquote><h3 id="🐞-bug-fixes-20" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-20" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue with demo environment settings</li><li>Fixed an error when a PDF template had a style of <code>none</code></li></ul><h2 id="version-5-0-1-—-pdf-layout-improvements" tabindex="-1">Version 5.0.1 — PDF Layout Improvements <a class="header-anchor" href="#version-5-0-1-—-pdf-layout-improvements" aria-label="Permalink to “Version 5.0.1 — PDF Layout Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 19, 2021</p></blockquote><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved PDF layout including explanatory text highlights, page breaks and banner overflow handling for long names and references</li></ul><h3 id="🐞-bug-fixes-21" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-21" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed read view handling of empty Scribble controls</li><li>Fixed a SQL Server 2016 driver issue following an operating system upgrade</li></ul><h2 id="version-5-0-0-—-form-instance-withdrawal-api-security" tabindex="-1">Version 5.0.0 — Form Instance Withdrawal &amp; API Security <a class="header-anchor" href="#version-5-0-0-—-form-instance-withdrawal-api-security" aria-label="Permalink to “Version 5.0.0 — Form Instance Withdrawal &amp; API Security”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 3, 2021</p></blockquote><h3 id="✨-new-features-7" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-7" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for multiple email addresses on email delivery channels</li><li>Added the ability to withdraw form instances using soft delete</li></ul><h3 id="⚡-improvements-10" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-10" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved styling of the field-value visibility toggle for the <code>xf:secret</code> control</li><li>Improved edit checks for clinician form template status</li><li>Improved performance monitoring instrumentation around plugins</li><li>Improved authorisation checks on APIs</li></ul><h2 id="version-4-30-2-—-patient-forms-api-fix" tabindex="-1">Version 4.30.2 — Patient Forms API Fix <a class="header-anchor" href="#version-4-30-2-—-patient-forms-api-fix" aria-label="Permalink to “Version 4.30.2 — Patient Forms API Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 3, 2021</p></blockquote><h3 id="🐞-bug-fixes-22" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-22" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue where the Patient Forms API returned only newly created forms</li></ul><h2 id="version-4-30-1-—-test-form-pdf-fix" tabindex="-1">Version 4.30.1 — Test Form PDF Fix <a class="header-anchor" href="#version-4-30-1-—-test-form-pdf-fix" aria-label="Permalink to “Version 4.30.1 — Test Form PDF Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 18, 2021</p></blockquote><h3 id="🐞-bug-fixes-23" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-23" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue where launching a test version of a form failed to generate a PDF on submission</li></ul><h2 id="version-4-30-0-—-wizard-rehydration-secret-control-oauth2" tabindex="-1">Version 4.30.0 — Wizard Rehydration, Secret Control &amp; OAuth2 <a class="header-anchor" href="#version-4-30-0-—-wizard-rehydration-secret-control-oauth2" aria-label="Permalink to “Version 4.30.0 — Wizard Rehydration, Secret Control &amp; OAuth2”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 11, 2021</p></blockquote><h3 id="✨-new-features-8" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-8" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added building block data rehydration for Wizard-style forms</li><li>Added support for the <code>xf:secret</code> control</li><li>Added support for hashing literal values from XPath using the XForms <code>digest()</code> function</li><li>Added OAuth2 machine-to-machine authorisation support to the AireFlow plugin</li><li>Added instance organisation ID to all form events</li></ul><h3 id="⚡-improvements-11" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-11" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Plugin loader now supports loading from multiple assemblies</li><li>Added <code>ServerBusyException</code> to the Exchange email retry policy</li><li>Retired or improved redundant features in the filesystem definition provider</li><li>Improved organisation configuration handling for form success URLs</li><li>Restored day, month and year attributes to Split Date for backwards compatibility</li></ul><h3 id="🐞-bug-fixes-24" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-24" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed the designer adding non-relevant attributes to controls after editing control settings</li><li>Resolved missing default value for <code>Include in External Notifications</code></li><li>Resolved long button text not wrapping on mobile</li><li>Resolved form titles covering organisation logos on mobile Safari</li></ul><h2 id="version-4-29-0-—-xpath-xsd-token-improvements" tabindex="-1">Version 4.29.0 — XPath, XSD &amp; Token Improvements <a class="header-anchor" href="#version-4-29-0-—-xpath-xsd-token-improvements" aria-label="Permalink to “Version 4.29.0 — XPath, XSD &amp; Token Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 21, 2021</p></blockquote><h3 id="✨-new-features-9" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-9" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added the CUI format Date Time function</li><li>Exposed key and version fields in the form designer for the server-side calculation control</li><li>Added the ability to mark a form as requiring a token</li></ul><h3 id="⚡-improvements-12" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-12" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved channel settings resolution to support multiple XPath rules</li><li>Improved CUI Date/Time functions to support empty values</li><li>Reordered XSD custom types from more specific to more generic to aid code generation</li><li>XSD generation now uses XSD data types rather than XForms data types when <code>RequiredXPath</code> is true</li><li>Added automatic redirect when a post-submission redirect exists and there is no delivery channel response to display</li><li>Reduced transformation service and reCAPTCHA logging</li><li>Updated the AireForms footer link</li><li>Wizard view on small screens now shows the organisation name when no logo is available</li></ul><h3 id="🐞-bug-fixes-25" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-25" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed a locale issue in CUI formatters</li></ul>`,162)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};